}

html,
body {
  margin: 0;
  min-width: 320px;
  min-height: 100%;
  background: var(--jk-color-canvas);
  color: var(--jk-color-text);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

button {
  font: inherit;
}

.app-shell {
  min-height: 100vh;
  background: var(--jk-color-canvas);
  color: var(--jk-color-text);
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--jk-space-4);
  padding: var(--jk-space-4) calc(var(--jk-space-4) * 1.5);
  border-bottom: 1px solid var(--jk-color-border);
  background: var(--jk-color-surface);
}

.topbar h1,
.panel h2,
.panel h3,
.panel p {
  margin-top: 0;
}

.topbar h1 {
  margin-bottom: var(--jk-space-2);
  font-size: 1.5rem;
  line-height: 1.2;
}

.topbar p {
  margin: 0;
  color: var(--jk-color-muted);
  font-size: 0.9rem;
}

.meeting-context {
  flex: 0 0 auto;
  padding: var(--jk-space-2) var(--jk-space-3);
  border: 1px solid var(--jk-color-border);
  border-radius: var(--jk-radius-control);
  color: var(--jk-color-muted);
  font-size: 0.82rem;
  font-weight: 650;
  white-space: nowrap;
}

.workspace {
  display: grid;
  grid-template-columns: minmax(220px, 0.72fr) minmax(440px, 1.7fr) minmax(310px, 1fr);
  gap: var(--jk-space-4);
  width: min(100%, 1480px);
  margin: 0 auto;
  padding: var(--jk-space-4);
  align-items: start;
}

.panel {
  min-width: 0;
  padding: var(--jk-space-4);
  border: 1px solid var(--jk-color-border);
  border-radius: var(--jk-radius-panel);
  background: var(--jk-color-surface);
}

.panel h2 {
  margin-bottom: var(--jk-space-2);
  font-size: 1rem;
  line-height: 1.3;
}

.panel h3 {
  margin-bottom: var(--jk-space-3);
  font-size: 0.88rem;
  line-height: 1.35;
}

.panel-subtitle,
.section-intro {
  margin-bottom: var(--jk-space-4);
  color: var(--jk-color-muted);
  font-size: 0.82rem;
  line-height: 1.45;
}

.queue-list,
.evidence-list,
.decision-options {
  display: grid;
  gap: var(--jk-space-3);
}

.queue-item {
  width: 100%;
  min-height: 76px;
  padding: var(--jk-space-3);
  border: 1px solid var(--jk-color-border);
  border-radius: var(--jk-radius-control);
  background: var(--jk-color-surface);
  color: var(--jk-color-text);
  text-align: left;
  cursor: pointer;
}

.queue-item:hover {
  border-color: var(--jk-color-focus);
}

.queue-item[aria-current="true"] {
  border-color: var(--jk-color-focus);
  box-shadow: inset 3px 0 0 var(--jk-color-focus);
}

.queue-topline,
.queue-meta,
.account-header,
.section-heading,
.evidence-item,
.receipt {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--jk-space-3);
}

.queue-id,
.eyebrow,
.evidence-label,
.handoff-row dt {
  color: var(--jk-color-muted);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.035em;
  text-transform: uppercase;
}

.queue-customer {
  display: block;
  margin: var(--jk-space-2) 0;
  font-size: 0.94rem;
  font-weight: 720;
  overflow-wrap: anywhere;
}

.queue-meta {
  color: var(--jk-color-muted);
  font-size: 0.76rem;
}

.queue-action {
  color: var(--jk-color-focus);
  font-weight: 700;
}

.detail-panel {
  padding: calc(var(--jk-space-4) + var(--jk-space-2));
}

.account-header {
  padding-bottom: var(--jk-space-4);
  border-bottom: 1px solid var(--jk-color-border);
}

.account-header h2 {
  margin: var(--jk-space-2) 0 0;
  font-size: 1.35rem;
}

.status-badge,
.evidence-state {
  flex: 0 0 auto;
  padding: var(--jk-space-2) var(--jk-space-3);
  border: 1px solid var(--jk-color-warning);
  border-radius: var(--jk-radius-control);
  color: var(--jk-color-warning);
  font-size: 0.75rem;
  font-weight: 720;
}

.facts-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin: 0;
  border-bottom: 1px solid var(--jk-color-border);
}

.facts-grid > div {
  min-width: 0;
  padding: var(--jk-space-4) var(--jk-space-3);
  border-right: 1px solid var(--jk-color-border);
}

.facts-grid > div:first-child {
  padding-left: 0;
}

.facts-grid > div:last-child {
  border-right: 0;
}

.facts-grid dt {
  margin-bottom: var(--jk-space-2);
  color: var(--jk-color-muted);
  font-size: 0.72rem;
}

.facts-grid dd {
  margin: 0;
  font-size: 0.9rem;
  font-weight: 680;
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}

.section-block {
  padding-top: var(--jk-space-4);
}

.section-heading {
  align-items: baseline;
}

.section-heading span {
  color: var(--jk-color-muted);
  font-size: 0.75rem;
}

.evidence-item {
  align-items: center;
  padding: var(--jk-space-3) var(--jk-space-4);
  border: 1px solid var(--jk-color-border);
  border-left: 3px solid var(--jk-color-success);
  border-radius: var(--jk-radius-control);
}

.evidence-item.state-error {
  border-left-color: var(--jk-color-risk);
}

.evidence-copy {
  min-width: 0;
}

.evidence-label {
  display: block;
  margin-bottom: var(--jk-space-2);
}

.evidence-value {
  display: block;
  font-size: 0.86rem;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.evidence-state.state-ready {
  border-color: var(--jk-color-success);
  color: var(--jk-color-success);
}

.evidence-state.state-empty,
.state-empty {
  border-color: var(--jk-color-warning);
  color: var(--jk-color-warning);
}

.evidence-state.state-error,
.state-error {
  border-color: var(--jk-color-risk);
  color: var(--jk-color-risk);
}

.policy-callout {
  padding: var(--jk-space-4);
  border: 1px solid var(--jk-color-warning);
  border-left: 3px solid var(--jk-color-warning);
  border-radius: var(--jk-radius-control);
}

.policy-callout h3 {
  color: var(--jk-color-warning);
}

.policy-callout p {
  margin-bottom: 0;
  color: var(--jk-color-text);
  font-size: 0.84rem;
  line-height: 1.5;
}

.decision-rail {
  display: grid;
  gap: var(--jk-space-4);
  min-width: 0;
}

.decision-option {
  display: block;
  width: 100%;
  min-height: 62px;
  padding: var(--jk-space-3) var(--jk-space-4);
  border: 1px solid var(--jk-color-border);
  border-radius: var(--jk-radius-control);
  background: var(--jk-color-surface);
  color: var(--jk-color-text);
  text-align: left;
  cursor: pointer;
}

.decision-option strong,
.decision-option span {
  display: block;
}

.decision-option strong {
  margin-bottom: var(--jk-space-2);
  font-size: 0.86rem;
}

.decision-option span {
  color: var(--jk-color-muted);
  font-size: 0.76rem;
  line-height: 1.4;
}

.decision-option[aria-pressed="true"] {
  border-color: var(--jk-color-focus);
  box-shadow: inset 3px 0 0 var(--jk-color-focus);
}

.decision-option:disabled,
.button:disabled {
  border-color: var(--jk-color-border);
  background: var(--jk-color-canvas);
  color: var(--jk-color-disabled);
  cursor: not-allowed;
}

.decision-option:disabled span {
  color: var(--jk-color-disabled);
}

.disabled-reason {
  margin: var(--jk-space-2) 0 0;
  color: var(--jk-color-disabled);
  font-size: 0.74rem;
  line-height: 1.4;
}

.action-row {
  display: flex;
  gap: var(--jk-space-3);
  margin-top: var(--jk-space-4);
}

.button {
  min-height: 44px;
  padding: var(--jk-space-3) var(--jk-space-4);
  border: 1px solid var(--jk-color-border);
  border-radius: var(--jk-radius-control);
  font-weight: 720;
  line-height: 1.2;
  cursor: pointer;
}

.button-primary {
  border-color: var(--jk-color-focus);
  background: var(--jk-color-focus);
  color: var(--jk-color-surface);
}

.button-secondary {
  background: var(--jk-color-surface);
  color: var(--jk-color-focus);
  border-color: var(--jk-color-focus);
}

.button-risk {
  background: var(--jk-color-surface);
  color: var(--jk-color-risk);
  border-color: var(--jk-color-risk);
}

.button:hover:not(:disabled),
.decision-option:hover:not(:disabled) {
  box-shadow: inset 0 0 0 1px var(--jk-color-focus);
}

button:focus-visible {
  outline: 2px solid var(--jk-color-focus);
  outline-offset: 2px;
  box-shadow: var(--jk-focus-ring);
}

.handoff-list {
  display: grid;
  gap: 0;
  margin: 0;
  border-top: 1px solid var(--jk-color-border);
}

.handoff-row {
  display: grid;
  grid-template-columns: 96px minmax(0, 1fr);
  gap: var(--jk-space-3);
  padding: var(--jk-space-3) 0;
  border-bottom: 1px solid var(--jk-color-border);
}

.handoff-row dt,
.handoff-row dd {
  margin: 0;
}

.handoff-row dd {
  font-size: 0.8rem;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.receipt {
  align-items: center;
  margin-top: var(--jk-space-4);
  padding: var(--jk-space-3);
  border: 1px solid var(--jk-color-receipt);
  border-radius: var(--jk-radius-control);
  color: var(--jk-color-receipt);
}

.receipt strong,
.receipt span {
  display: block;
}

.receipt strong {
  margin-bottom: var(--jk-space-2);
  font-size: 0.8rem;
}

.receipt span {
  font-size: 0.72rem;
  line-height: 1.35;
}

.state-loading {
  cursor: progress;
  color: var(--jk-color-muted);
}

.state-loading::after {
  content: "Loading…";
  margin-left: var(--jk-space-2);
}

@media (max-width: 1080px) {
  .workspace {
    grid-template-columns: minmax(210px, 0.7fr) minmax(0, 1.6fr);
  }

  .decision-rail {
    grid-column: 1 / -1;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .facts-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .facts-grid > div:nth-child(2) {
    border-right: 0;
  }
}

@media (max-width: 720px) {
  .topbar {
    align-items: flex-start;
    flex-direction: column;
  }

  .meeting-context {
    white-space: normal;
  }

  .workspace {
    grid-template-columns: minmax(0, 1fr);
  }

  .queue-panel {
    order: 1;
  }

  .decision-rail {
    order: 2;
    grid-column: auto;
    grid-template-columns: minmax(0, 1fr);
  }

  .detail-panel {
    order: 3;
  }

  .facts-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .facts-grid > div,
  .facts-grid > div:first-child {
    padding: var(--jk-space-3) 0;
    border-right: 0;
    border-bottom: 1px solid var(--jk-color-border);
  }

  .facts-grid > div:last-child {
    border-bottom: 0;
  }

  .account-header,
  .evidence-item,
  .receipt {
    align-items: flex-start;
    flex-direction: column;
  }

  .action-row,
  .action-row .button,
  .receipt .button {
    width: 100%;
  }
}

@media (forced-colors: active) {
  button,
  .panel,
  .status-badge,
  .evidence-item,
  .policy-callout,
  .receipt {
    border: 1px solid currentColor;
  }
}

