  outline: 2px solid var(--jk-color-focus);
  outline-offset: 2px;
  box-shadow: var(--jk-focus-ring);
}

.handoff-list {
  display: grid;
  gap: 0;
  margin: 0;
  border-top: 1px solid var(--jk-color-border);
}

.handoff-row {
  display: grid;
  grid-template-columns: 96px minmax(0, 1fr);
  gap: var(--jk-space-3);
  padding: var(--jk-space-3) 0;
  border-bottom: 1px solid var(--jk-color-border);
}

.handoff-row dt,
.handoff-row dd {
  margin: 0;
}

.handoff-row dd {
  font-size: 0.8rem;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.receipt {
  align-items: center;
  margin-top: var(--jk-space-4);
  padding: var(--jk-space-3);
  border: 1px solid var(--jk-color-receipt);
  border-radius: var(--jk-radius-control);
  color: var(--jk-color-receipt);
}

.receipt strong,
.receipt span {
  display: block;
}

.receipt strong {
  margin-bottom: var(--jk-space-2);
  font-size: 0.8rem;
}

.receipt span {
  font-size: 0.72rem;
  line-height: 1.35;
}

.state-loading {
  cursor: progress;
  color: var(--jk-color-muted);
}

.state-loading::after {
